import { Arrow, BoxNode, Diagram } from "@flanksource/facet";
import "./page.css";
export default function DeploymentDiagram() { return <main className="p-8"><h1 className="text-2xl font-bold">Deployment path</h1><Diagram className="p-8">{(id) => <div className="flex items-center justify-between gap-16"><BoxNode id={id("source")} title="Source" className="w-64">Approved change</BoxNode><BoxNode id={id("target")} title="Deployment" className="w-64">Running service</BoxNode><Arrow from={id("source")} to={id("target")} /></div>}</Diagram></main>; }
